<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>GlobalBank - Secure Transfer</title>
</head>
<body>

<h2>GlobalBank Secure Transfer Form</h2>

<!-- 
    NOTE: In a real-world scenario, the 'action' URL should be served over HTTPS.
    The PHP code below simulates the server-side logic that generates the token.
-->

<form action="secure_transfer_handler.php" method="POST">

    <!-- CSRF Protection Token -->
    <input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token']); ?>">

    <label for="fromAccount">Transfer From (Account Number):</label><br>
    <input type="text" id="fromAccount" name="fromAccount" required><br>

    <label for="toAccount">Transfer To (Account Number):</label><br>
    <input type="text" id="toAccount" name="toAccount" required><br>

    <label for="amount">Amount:</label><br>
    <input type="number" id="amount" name="amount" step="0.01" required><br><br>

    <input type="submit" value="Submit Transfer">
</form>

</body>
</html>
